using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using LiveCG.App;
using LiveCG.Core;
using SkiaSharp;

internal static class DirectUiChecks
{
    public static void Run(MainWindow window,string folder,Action<bool,string> check)
    {
        T C<T>(string n)=>(T)window.FindName(n);T Field<T>(string n)=>(T)typeof(MainWindow).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(window)!;
        object? Call(string n,params object?[] v){var m=typeof(MainWindow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic)!;return m.Invoke(window,m.GetParameters().Select((p,i)=>i<v.Length?v[i]:p.DefaultValue).ToArray());}
        void Pump()=>Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);ImageJob Job()=>Field<ImageJob>("_current");
        var path=Path.Combine(folder,"타임라인 예제.png");window.ApplyDocument(new(){Jobs=[new(){SourcePath=path,Width=960,Height=540}],Video=new(){Fps=30,EndHold=.5}});C<CheckBox>("AutoFocusCheck").IsChecked=false;C<CheckBox>("HideOverlaysCheck").IsChecked=false;if(window.IsEditorFocused)Call("ToggleFocusMode",window,new RoutedEventArgs());Pump();
        var p=C<PreviewControl>("Preview");var timeline=C<TimelineControl>("TimelineEditor");C<ComboBox>("CreationRoleBox").SelectedIndex=0;C<ComboBox>("ShapeBox").SelectedIndex=0;
        SKPoint At(float x,float y)=>p.Viewport.ToScreen(new SKPoint(x,y));
        void Draw(float x,float y,float w,float h){Call("SetDrawMode",true);p.BeginPointer(At(x,y));p.MovePointer(At(x+w,y+h));p.EndPointer();Pump();}
        Draw(80,80,400,320);var group=Job().Regions.Single();group.Clips.Add(new(){Start=1,Duration=3,Options=new(){Kind=EffectKind.RiseIn}});Call("SelectRegion",group);var groupId=group.Id;var original=JsonSerializer.Serialize(group);
        C<ComboBox>("ShapeBox").SelectedIndex=1;check(group.Shape==RegionShape.Rectangle&&JsonSerializer.Serialize(group)==original&&p.AddMode,"choosing the next ellipse leaves the earlier rectangle and its effects unchanged");p.BeginPointer(At(200,180));p.MovePointer(At(260,240));p.EndPointer();var child=Job().Regions.First(r=>r.Id!=groupId);check(child.Shape==RegionShape.Ellipse&&child.ParentId==groupId&&group.Shape==RegionShape.Rectangle,"next mouse drawing creates its chosen shape inside the previous group");
        C<ComboBox>("ShapeBox").SelectedIndex=4;p.AddPathPoint(At(600,100));p.AddPathPoint(At(800,100));p.AddPathPoint(At(700,300));p.FinishPath();var polygon=Job().Regions.First(r=>r.Shape==RegionShape.Polygon);var polygonId=polygon.Id;Call("TogglePointEditing",window,new RoutedEventArgs());var vertices=p.PathScreenPoints();var old=vertices[0];p.BeginPointer(old);p.MovePointer(new(old.X-15,old.Y+12));p.EndPointer();check(SKPoint.Distance(p.PathScreenPoints()[0],old)>10,"completed pen path vertex can be dragged outside its previous bounds");
        Call("UndoEdit",window,new RoutedEventArgs());polygon=Job().Regions.First(r=>r.Id==polygonId);check(SKPoint.Distance(p.PathScreenPoints()[0],old)<.01,"vertex drag is restored by global undo");
        vertices=p.PathScreenPoints();var mid=new SKPoint((vertices[0].X+vertices[1].X)/2,(vertices[0].Y+vertices[1].Y)/2);p.BeginPointer(mid);p.EndPointer();check(polygon.Points.Count==4,"clicking a completed path segment inserts a vertex");check(p.DeleteSelectedPathPoint()&&polygon.Points.Count==3,"selected pen vertex can be deleted while keeping a closed valid path");Call("UndoEdit",window,new RoutedEventArgs());polygon=Job().Regions.First(r=>r.Id==polygonId);check(polygon.Points.Count==4,"undo restores a deleted path vertex");
        vertices=p.PathScreenPoints();var beforePath=JsonSerializer.Serialize(polygon);p.BeginPointer(vertices[0]);p.MovePointer(new(vertices[0].X+20,vertices[0].Y+20));p.CancelGesture();check(JsonSerializer.Serialize(polygon)==beforePath,"ESC cancels a path point move with exact geometry restoration");
        group=Job().Regions.First(r=>r.Id==groupId);Call("SelectRegion",group);Call("DrawNewMask",window,new RoutedEventArgs());p.NewShape=RegionShape.Ellipse;p.BeginPointer(At(150,140));p.MovePointer(At(330,300));p.EndPointer();var mask=group.Masks.Single();check(mask.Start==1&&mask.Duration==3&&mask.EndMode==MaskEndMode.Release&&mask.StartAtInPoint,"first new mask adopts its parent clip interval and only applies inside it");
        timeline.SnapEnabled=false;var r=timeline.MaskRect(mask);timeline.BeginPointer(new(r.Left+1,r.Top+14));timeline.MovePointer(new(r.Left+1+.5*timeline.PixelsPerSecond,r.Top+14),true);timeline.EndPointer();check(Math.Abs(mask.Start-1.5)<.001&&Math.Abs(mask.End-4)<.001,"first interaction can trim the newly created mask left edge");Call("UndoEdit",window,new RoutedEventArgs());group=Job().Regions.First(x=>x.Id==groupId);mask=group.Masks.Single();Call("SelectRegion",group);r=timeline.MaskRect(mask);timeline.BeginPointer(new(r.Right+3,r.Top+14));timeline.MovePointer(new(r.Right+3-.5*timeline.PixelsPerSecond,r.Top+14),true);timeline.EndPointer();check(Math.Abs(mask.Start-1)<.001&&Math.Abs(mask.End-3.5)<.001,"unselected mask right edge supports immediate drag from its visible handle margin");
        var rows=LayerGraph.Rows(Job().Regions);var rootRow=rows.First(x=>x.Region.Id==group.Id&&x.Mask is null);var childRow=rows.First(x=>x.Region.ParentId==group.Id&&x.Mask is null);var maskRow=rows.First(x=>x.Mask==mask);check(TimelineControl.HeaderIndent(childRow)>TimelineControl.HeaderIndent(rootRow)&&TimelineControl.HeaderIndent(maskRow)>TimelineControl.HeaderIndent(rootRow),"group children and masks have a genuine shared indented hierarchy");check(Math.Abs(timeline.MaskRect(mask).Left-timeline.ClipRect(group,group.Clips[0]).Left)<.01,"hierarchy indentation preserves common timeline time alignment");
        window.SelectMask(group,mask);var mouse=window.MouseProperties["MaskOpacityBox"];mouse.BeginEdit();mouse.EditValue(60);mouse.EditValue(40);mouse.EndEdit(true);check(Math.Abs(mask.Opacity-.4)<.001,"mask opacity slider updates the actual mask immediately");Call("UndoEdit",window,new RoutedEventArgs());group=Job().Regions.First(x=>x.Id==groupId);mask=group.Masks.Single();check(mask.Opacity==1,"one undo restores an entire continuous slider drag");
        Call("SelectRegion",group,group.Clips[0]);mouse=window.MouseProperties["ClipDurationBox"];mouse.BeginEdit();mouse.EditValue(5);mouse.EndEdit(false);group=Job().Regions.First(x=>x.Id==groupId);mask=group.Masks.Single();check(group.Clips[0].Duration==3,"cancelled clip duration slider restores the original document");
        window.SelectMask(group,mask);StudioUiChecks.Capture(window,Path.Combine(folder,"mouse-hierarchy.png"),1568,1000);
        var dialog=new MaskAnimationWindow(path,mask){Owner=window,WindowStartupLocation=WindowStartupLocation.Manual,Left=-15000,Top=-15000,ShowActivated=false,ShowInTaskbar=false};
        try
        {
            dialog.Show();Pump();var preview=dialog.Preview;var screen=new SKPoint(200,100);var sourcePoint=preview.Viewport.ToImage(screen);preview.ZoomAt(2,screen);check(SKPoint.Distance(preview.Viewport.ToImage(screen),sourcePoint)<.01,"mask preview zoom preserves the source pixel beneath the mouse");var pan=preview.Viewport.Pan;preview.BeginPointer(screen,true);preview.MovePointer(new(230,120));preview.EndPointer(true);check(Math.Abs(preview.Viewport.Pan.X-pan.X-30)<.01,"mask preview supports space or middle-button pan");preview.Fit();check(preview.Viewport.Zoom==1&&preview.Viewport.Pan==default,"mask preview fit resets zoom and pan");
            preview.Native();check(Math.Abs(preview.Viewport.Scale*System.Windows.Media.VisualTreeHelper.GetDpi(preview).DpiScaleX-1)<.001,"mask native zoom maps source pixels to physical display pixels");preview.Fit();dialog.SetFrame(15);var anchor=preview.ScreenAnchor();preview.BeginTransform(0,anchor);preview.MoveTransform(new(anchor.X+20,anchor.Y+10));preview.EndTransform(true);check(dialog.Result.Value(MotionProperty.X,15)>0&&dialog.Result.Value(MotionProperty.Y,15)>0,"dragging the mask body creates position keys at the current frame");dialog.Undo();check(dialog.Result.Value(MotionProperty.X,15)==0,"mask body drag is one reversible key edit");
            var corner=preview.ScreenHandles()[4];preview.BeginTransform(1,corner,4);preview.MoveTransform(new(corner.X+20,corner.Y+20));preview.EndTransform(true);check(dialog.Result.Value(MotionProperty.ScaleX,15)>1&&dialog.Result.Value(MotionProperty.ScaleY,15)>1,"mask corner drag creates scale keys");dialog.Undo();
            var rotation=preview.RotationHandle();anchor=preview.ScreenAnchor();preview.BeginTransform(2,rotation);preview.MoveTransform(new(anchor.X+50,anchor.Y));preview.EndTransform(true);check(Math.Abs(dialog.Result.Value(MotionProperty.Rotation,15))>20,"mask rotation handle changes visible rotation");dialog.Undo();
            dialog.SetKey(MotionProperty.ScaleX,15,1.3);dialog.SetKey(MotionProperty.Rotation,15,30);var corners=preview.ScreenCorners();anchor=preview.ScreenAnchor();preview.BeginTransform(3,anchor);preview.MoveTransform(new(anchor.X+12,anchor.Y+9));preview.EndTransform(true);check(dialog.Result.Value(MotionProperty.AnchorX,15)!=.5&&corners.Zip(preview.ScreenCorners()).All(pair=>SKPoint.Distance(pair.First,pair.Second)<.02),"moving mask anchor preserves its visible transformed position");dialog.Undo();
            var property=(ComboBox)typeof(MaskAnimationWindow).GetField("_property",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!;
            foreach(var channel in Enum.GetValues<MotionProperty>())
            {
                property.SelectedIndex=(int)channel;var value=channel==MotionProperty.Rotation?25:channel==MotionProperty.Opacity?40:channel is MotionProperty.AnchorX or MotionProperty.AnchorY?60:channel is MotionProperty.ScaleX or MotionProperty.ScaleY?130:10;dialog.PropertyMouse.BeginEdit();dialog.PropertyMouse.EditValue(value);dialog.PropertyMouse.EndEdit(true);check(Math.Abs(dialog.Result.Value(channel,15)-value/(channel==MotionProperty.Rotation?1d:100d))<.001,"mask mouse property edits "+channel);dialog.Undo();
            }
            var priorLength=dialog.Result.LengthFrames;dialog.LengthMouse.BeginEdit();dialog.LengthMouse.EditValue(priorLength*2);dialog.LengthMouse.EndEdit(true);check(dialog.Result.LengthFrames==priorLength*2&&dialog.Result.Tracks.SelectMany(t=>t.Keys).All(k=>k.Frame<=dialog.Result.LengthFrames),"mask length slider rescales keys into the new frame range");dialog.Undo();check(dialog.Result.LengthFrames==priorLength,"mask authoring-length slider is reversible");
            StudioUiChecks.Capture(dialog,Path.Combine(folder,"mouse-mask-editor.png"),1210,850);StudioUiChecks.Capture(dialog,Path.Combine(folder,"mouse-mask-minimum.png"),900,650);
        }finally{dialog.Close();}
        var studio=new EffectStudioWindow(new(){Name="마우스 조절 검증",Clips=[new(){Duration=2,Options=new(){Kind=EffectKind.UserMotion},Motion=new()}]}){Owner=window,WindowStartupLocation=WindowStartupLocation.Manual,Left=-15000,Top=-15000,ShowActivated=false,ShowInTaskbar=false};
        try{studio.Show();Pump();var property=(ComboBox)typeof(EffectStudioWindow).GetField("_property",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(studio)!;property.SelectedIndex=(int)MotionProperty.Opacity;studio.PropertyMouse.BeginEdit();studio.PropertyMouse.EditValue(25);studio.PropertyMouse.EndEdit(true);check(studio.Timeline.Motion.Value(MotionProperty.Opacity,0)==.25,"effect studio also supports immediate mouse property editing");studio.Undo();check(studio.Timeline.Motion.Value(MotionProperty.Opacity,0)==1,"effect studio slider undo restores the original value");studio.LengthMouse.BeginEdit();studio.LengthMouse.EditValue(90);studio.LengthMouse.EndEdit(true);check(studio.Timeline.Motion.LengthFrames==90&&studio.Asset.Duration==3,"effect studio mouse length editing updates the actual asset duration");studio.Undo();check(studio.Timeline.Motion.LengthFrames==60,"effect studio mouse length editing can be undone");}finally{studio.DiscardAndClose();}
        C<ComboBox>("MaskStartBox").Text="0";Call("MaskPropertiesChanged",window,new RoutedEventArgs());var endAtZero=mask.End;r=timeline.MaskRect(mask);timeline.BeginPointer(new(r.Left-3,r.Top+14));timeline.MovePointer(new(r.Left-3+.3*timeline.PixelsPerSecond,r.Top+14),true);timeline.EndPointer();check(Math.Abs(mask.Start-.3)<.001&&Math.Abs(mask.End-endAtZero)<.001,"mask in-point at zero can be grabbed just outside the left handle without hitting header arrows");
        C<ComboBox>("ShapeBox").SelectedIndex=2;Call("ChangeSelectedShape",window,new RoutedEventArgs());check(mask.Shape==RegionShape.RoundedRectangle&&group.Shape==RegionShape.Rectangle,"explicit mask shape editing preserves the parent group shape");
        Call("DrawNewMask",window,new RoutedEventArgs());p.NewShape=RegionShape.Polygon;p.AddPathPoint(At(200,150));p.AddPathPoint(At(350,150));p.AddPathPoint(At(280,270));p.FinishPath();var pathMask=group.Masks.Last();var groupBounds=group.Bounds;Call("TogglePointEditing",window,new RoutedEventArgs());var maskPoints=p.PathScreenPoints();p.BeginPointer(maskPoints[0]);p.MovePointer(new(maskPoints[0].X-10,maskPoints[0].Y+8));p.EndPointer();check(group.Bounds==groupBounds&&SKPoint.Distance(maskPoints[0],p.PathScreenPoints()[0])>5,"mask pen-point editing changes only the mask and preserves its parent bounds");
        var pathFile=Path.Combine(folder,"mouse-path-template.json");DocumentStore.Save(pathFile,new TemplateDocument{Regions=LayerGraph.Copy(Job().Regions)});var loaded=DocumentStore.Load<TemplateDocument>(pathFile);check(loaded.Regions.First(x=>x.Name==group.Name&&x.Role==RegionRole.Group).Masks.Last().Points.SequenceEqual(pathMask.Points),"edited mask vertices survive template serialization");
        var scrub=new MouseValueControl();scrub.Configure(0,100,"%");scrub.SetSilently(50);scrub.BeginEdit();scrub.ScrubBy(10,true);scrub.EndEdit(true);check(Math.Abs(scrub.Value-51)<.001,"Shift value scrubbing provides ten times finer mouse control");
        Call("SetDrawMode",false);
    }
}
